insert into public.legal_documents (slug, language, version, effective_at, title, summary, sections, status) values
  ('legal_notice', 'es', '1.0', '2026-10-01T00:00:00Z', 'Aviso Legal', 'Quién está detrás de Nightlife Connect y cómo contactarnos.', '[{"heading":"Titular","body":"[DATOS EMPRESA: razón social, NIF, domicilio social, datos registrales y email de contacto]."},{"heading":"Punto de contacto DSA","body":"Punto único de contacto para autoridades y usuarios (Reglamento de Servicios Digitales, arts. 11 y 12): [DATOS EMPRESA: email]. Idiomas: español e inglés."},{"heading":"Propiedad intelectual","body":"La marca, el diseño y el código pertenecen al titular. Los contenidos publicados por los usuarios son suyos; nos dan una licencia limitada para mostrarlos en el servicio."},{"heading":"Responsabilidad","body":"La información de locales y eventos es orientativa. Las estadísticas son agregadas y anónimas y pueden no reflejar la realidad exacta."}]'::jsonb, 'published'),
  ('legal_notice', 'en', '1.0', '2026-10-01T00:00:00Z', 'Legal Notice', 'Who is behind Nightlife Connect and how to reach us.', '[{"heading":"Owner","body":"[COMPANY DATA: legal name, tax ID, registered address, registry data and contact email]."},{"heading":"DSA point of contact","body":"Single point of contact for authorities and users (Digital Services Act, arts. 11 and 12): [COMPANY DATA: email]. Languages: Spanish and English."},{"heading":"Intellectual property","body":"The brand, design and code belong to the owner. Content posted by users is theirs; they grant us a limited licence to show it in the service."},{"heading":"Liability","body":"Venue and event information is indicative. Stats are aggregated and anonymous and may not reflect reality exactly."}]'::jsonb, 'published'),
  ('terms', 'es', '1.0', '2026-10-01T00:00:00Z', 'Términos y Condiciones', 'Las reglas del servicio: quién puede usarlo, qué ofrecemos y qué no está permitido.', '[{"heading":"Quiénes somos","body":"Nightlife Connect es un servicio de [DATOS EMPRESA: razón social, NIF, domicilio, email de contacto]."},{"heading":"Solo mayores de edad","body":"El servicio es exclusivamente para mayores de 18 años. Para ver perfiles, dar likes, chatear, marcar «Voy», hacer check-in visible o crear eventos es obligatorio verificar la mayoría de edad."},{"heading":"Qué ofrecemos","body":"Información en tiempo real sobre locales y eventos, estadísticas agregadas y anónimas de afluencia y herramientas para conocer gente. Las funciones básicas, las verificaciones y la seguridad son siempre gratuitas."},{"heading":"Tu cuenta","body":"Una cuenta por persona y por teléfono. Eres responsable de lo que publiques. Puedes eliminar tu cuenta cuando quieras desde la app."},{"heading":"Moderación","body":"Aplicamos las Normas de la Comunidad. Las decisiones se explican y puedes recurrirlas; siempre las revisa una persona."},{"heading":"Ley aplicable","body":"Legislación española. [DATOS EMPRESA: jurisdicción y datos de resolución de litigios]."}]'::jsonb, 'published'),
  ('terms', 'en', '1.0', '2026-10-01T00:00:00Z', 'Terms and Conditions', 'The service rules: who can use it, what we offer and what is not allowed.', '[{"heading":"Who we are","body":"Nightlife Connect is a service of [COMPANY DATA: legal name, tax ID, address, contact email]."},{"heading":"Adults only","body":"The service is only for people aged 18 or over. Viewing profiles, liking, chatting, marking “Going”, visible check-ins and creating events require age verification."},{"heading":"What we offer","body":"Real-time information about venues and events, aggregated anonymous crowd statistics and tools to meet people. Core features, verifications and safety are always free."},{"heading":"Your account","body":"One account per person and phone number. You are responsible for what you post. You can delete your account at any time from the app."},{"heading":"Moderation","body":"We apply the Community Guidelines. Decisions are explained and can be appealed; a person always reviews them."},{"heading":"Governing law","body":"Spanish law. [COMPANY DATA: jurisdiction and dispute resolution details]."}]'::jsonb, 'published'),
  ('community', 'es', '1.0', '2026-10-01T00:00:00Z', 'Normas de la Comunidad', 'Respeto, consentimiento y seguridad. Lo que hace que la noche funcione para todos.', '[{"heading":"Respeto y consentimiento","body":"No se toleran el acoso, la insistencia tras un «no», el odio ni la discriminación. El semáforo rojo significa invisible: respétalo."},{"heading":"Personas reales","body":"Tus fotos tienen que ser tuyas y actuales. Prohibido suplantar a otras personas o crear perfiles falsos."},{"heading":"Nada de menores","body":"Si sospechas que alguien es menor, repórtalo con el motivo «posible menor». Suspendemos la cuenta de forma cautelar."},{"heading":"Eventos honestos","body":"Solo en lugares públicos y reales. Los eventos falsos se ocultan tras 3 reportes y se revisan."},{"heading":"Tres avisos","body":"3 reportes válidos en 6 horas suspenden la cuenta hasta la revisión humana."}]'::jsonb, 'published'),
  ('community', 'en', '1.0', '2026-10-01T00:00:00Z', 'Community Guidelines', 'Respect, consent and safety. What makes the night work for everyone.', '[{"heading":"Respect and consent","body":"No harassment, no insisting after a “no”, no hate or discrimination. A red light means invisible: respect it."},{"heading":"Real people","body":"Your photos must be yours and recent. Impersonation and fake profiles are forbidden."},{"heading":"No minors","body":"If you suspect someone is a minor, report them with the “possible minor” reason. We suspend the account as a precaution."},{"heading":"Honest events","body":"Only in real public places. Fake events are hidden after 3 reports and reviewed."},{"heading":"Three strikes","body":"3 valid reports within 6 hours suspend the account until a human review."}]'::jsonb, 'published'),
  ('privacy', 'es', '1.0', '2026-10-01T00:00:00Z', 'Política de Privacidad', 'Qué datos tratamos, para qué, con qué base legal, cuánto tiempo y cuáles son tus derechos.', '[{"heading":"Responsable","body":"[DATOS EMPRESA: razón social, NIF, domicilio, email del Delegado de Protección de Datos]."},{"heading":"Qué tratamos","body":"Teléfono (y email opcional), fecha de nacimiento declarada, perfil, preferencias (solo con tu consentimiento explícito), check-ins sin posición GPS, likes, matches y mensajes, y resultados de verificación como sí/no."},{"heading":"Lo que nunca guardamos","body":"DNI, imágenes de documentos, selfies, vídeos ni descriptores faciales. Las fotos se suben sin metadatos de ubicación."},{"heading":"Bases legales","body":"Contrato, interés legítimo (seguridad y antifraude), protección de menores, obligación legal y tu consentimiento, que puedes retirar en cualquier momento."},{"heading":"Plazos","body":"Check-ins 30 días, objetos perdidos 48 horas, datos técnicos 90 días, moderación 2 años. El resto, mientras la cuenta esté activa."},{"heading":"Tus derechos","body":"Acceso, rectificación, supresión, oposición, limitación y portabilidad desde Privacidad y datos, con respuesta en un mes como máximo. Puedes reclamar ante la AEPD."},{"heading":"Terceros","body":"Proveedores en la UE o con garantías adecuadas. Consulta la lista pública de terceros."}]'::jsonb, 'published'),
  ('privacy', 'en', '1.0', '2026-10-01T00:00:00Z', 'Privacy Policy', 'Which data we process, why, on which legal basis, for how long and your rights.', '[{"heading":"Controller","body":"[COMPANY DATA: legal name, tax ID, address, Data Protection Officer email]."},{"heading":"What we process","body":"Phone (and optional email), declared date of birth, profile, preferences (only with your explicit consent), check-ins without GPS position, likes, matches and messages, and verification results as yes/no."},{"heading":"What we never keep","body":"ID numbers, document images, selfies, videos or face descriptors. Photos are uploaded without location metadata."},{"heading":"Legal bases","body":"Contract, legitimate interest (safety and anti-fraud), protection of minors, legal obligation and your consent, which you can withdraw at any time."},{"heading":"Retention","body":"Check-ins 30 days, lost & found 48 hours, technical data 90 days, moderation 2 years. Everything else while the account is active."},{"heading":"Your rights","body":"Access, rectification, erasure, objection, restriction and portability from Privacy & data, answered within one month. You can complain to the Spanish DPA (AEPD)."},{"heading":"Third parties","body":"Providers in the EU or with adequate safeguards. See the public third-party list."}]'::jsonb, 'published'),
  ('cookies', 'es', '1.0', '2026-10-01T00:00:00Z', 'Política de Cookies y Tecnologías Similares', 'Solo usamos almacenamiento técnico necesario. Sin cookies de publicidad ni rastreo.', '[{"heading":"Qué usamos","body":"Almacenamiento local del navegador para recordar tu sesión, tu tema, el idioma y tus preferencias de movimiento. Son técnicos y necesarios para que el servicio funcione."},{"heading":"Qué no usamos","body":"No hay cookies de publicidad, ni redes de anuncios, ni píxeles de seguimiento de terceros."},{"heading":"Analítica","body":"Solo si la aceptas en el onboarding o en Ajustes, autoalojada o en la UE, y como máximo 13 meses. Puedes retirarla cuando quieras."}]'::jsonb, 'published'),
  ('cookies', 'en', '1.0', '2026-10-01T00:00:00Z', 'Cookies and Similar Technologies Policy', 'We only use necessary technical storage. No advertising or tracking cookies.', '[{"heading":"What we use","body":"Browser local storage to remember your session, theme, language and motion preferences. They are technical and necessary for the service to work."},{"heading":"What we do not use","body":"No advertising cookies, ad networks or third-party tracking pixels."},{"heading":"Analytics","body":"Only if you accept it during onboarding or in Settings, self-hosted or in the EU, for 13 months at most. You can withdraw it any time."}]'::jsonb, 'published'),
  ('ranking', 'es', '1.0', '2026-10-01T00:00:00Z', 'Transparencia de Clasificación y Patrocinados', 'Cómo ordenamos locales, eventos y personas, y cómo se marcan los patrocinios.', '[{"heading":"Orden en el mapa y en las listas","body":"Por distancia, si está abierto y afluencia en directo. Los filtros que eliges se aplican siempre antes que cualquier otro criterio."},{"heading":"Patrocinados","body":"Llevan siempre la etiqueta «Patrocinado», solo aparecen si cumplen tus filtros, los huecos son limitados y nunca alteran las estadísticas."},{"heading":"Personas","body":"El emparejamiento funciona por reglas, sin IA: compatibilidad mutua, cercanía y actividad de esta noche. Las ventajas de pago dan visibilidad, nunca saltan los filtros ni el semáforo de la otra persona."}]'::jsonb, 'published'),
  ('ranking', 'en', '1.0', '2026-10-01T00:00:00Z', 'Ranking and Sponsored Content Transparency', 'How we order venues, events and people, and how sponsorships are labelled.', '[{"heading":"Order on the map and in lists","body":"By distance, whether it is open and live attendance. The filters you choose always apply before any other criterion."},{"heading":"Sponsored","body":"Always labelled \"Sponsored\", only shown if they match your filters, with limited slots, and they never alter the stats."},{"heading":"People","body":"Matching is rule-based, without AI: mutual compatibility, proximity and tonight’s activity. Paid perks give visibility; they never skip filters or the other person’s traffic light."}]'::jsonb, 'published'),
  ('venues', 'es', '1.0', '2026-10-01T00:00:00Z', 'Condiciones para Locales y Organizadores', 'Reclamar y gestionar la ficha de tu local es gratis.', '[{"heading":"Reclamar la ficha","body":"Debes acreditar que gestionas el local. Revisamos cada solicitud a mano antes de darte acceso."},{"heading":"Qué puedes hacer","body":"Editar descripción, horario y precio, publicar eventos oficiales y ver estadísticas agregadas (nunca datos de personas concretas, y solo con un mínimo de asistentes)."},{"heading":"Obligaciones","body":"Información veraz, respeto de la normativa de alcohol y de tu comunidad autónoma, y de las Normas de la Comunidad."}]'::jsonb, 'published'),
  ('venues', 'en', '1.0', '2026-10-01T00:00:00Z', 'Terms for Venues and Organisers', 'Claiming and managing your venue’s page is free.', '[{"heading":"Claiming the page","body":"You must prove you manage the venue. We review every request by hand before granting access."},{"heading":"What you can do","body":"Edit description, opening hours and price, publish official events and see aggregated stats (never individual data, and only above a minimum number of people)."},{"heading":"Obligations","body":"Truthful information, compliance with alcohol rules in your region, and with the Community Guidelines."}]'::jsonb, 'published'),
  ('sponsorship', 'es', '1.0', '2026-10-01T00:00:00Z', 'Condiciones de Patrocinio', 'Tres niveles (Destacado, Destacado Plus y Top) con reglas fijas.', '[{"heading":"Niveles","body":"Destacado, Destacado Plus y Top. [PRECIOS A DEFINIR]. En el MVP se contratan por factura y los activa el equipo."},{"heading":"Reglas fijas","body":"Etiqueta siempre visible, sin alterar datos, solo si cumple los filtros del usuario y con huecos limitados."},{"heading":"Alcohol y Flash Alerts","body":"Solo a mayores con edad verificada que lo hayan consentido y según la normativa autonómica."}]'::jsonb, 'published'),
  ('sponsorship', 'en', '1.0', '2026-10-01T00:00:00Z', 'Sponsorship Terms', 'Three tiers (Featured, Featured Plus and Top) with fixed rules.', '[{"heading":"Tiers","body":"Featured, Featured Plus and Top. [PRICES TBD]. In the MVP they are invoiced and activated by the team."},{"heading":"Fixed rules","body":"Label always visible, data never altered, only shown if it matches the user’s filters, with limited slots."},{"heading":"Alcohol and Flash Alerts","body":"Only to age-verified adults who consented, and according to regional rules."}]'::jsonb, 'published'),
  ('premium', 'es', '1.0', '2026-10-01T00:00:00Z', 'Condiciones de Premium', 'Suscripciones, pase de una noche y extras sueltos. Lo básico y la seguridad siempre son gratis.', '[{"heading":"Qué compras","body":"Ventajas de comodidad (Pase, Pase VIP, Pase de una noche) y extras sueltos (Chispas, Foco, Mensaje directo). Precios con IVA incluido antes de pagar."},{"heading":"Renovación y cancelación","body":"Las suscripciones se renuevan cada mes hasta que canceles en dos toques desde Mi suscripción. Mantienes las ventajas hasta el final del periodo pagado."},{"heading":"Desistimiento","body":"Tienes 14 días desde la compra para desistir desde Mi suscripción, con reembolso completo. En las apps, las compras las gestiona la tienda (Apple o Google) según sus condiciones."},{"heading":"Pagos","body":"Los procesa una pasarela segura (Stripe en la web; App Store o Google Play en las apps). Nunca vemos ni guardamos tu tarjeta. Facturas disponibles en Mi suscripción."}]'::jsonb, 'inactive'),
  ('premium', 'en', '1.0', '2026-10-01T00:00:00Z', 'Premium Terms', 'Subscriptions, one-night pass and extras. The basics and safety are always free.', '[{"heading":"What you buy","body":"Comfort perks (Pass, VIP Pass, One-night pass) and extras (Sparks, Spotlight, Direct message). Prices include VAT and are shown before paying."},{"heading":"Renewal and cancellation","body":"Subscriptions renew every month until you cancel in two taps from My subscription. You keep the perks until the end of the paid period."},{"heading":"Withdrawal","body":"You have 14 days from purchase to withdraw from My subscription, with a full refund. In the apps, purchases are handled by the store (Apple or Google) under its terms."},{"heading":"Payments","body":"Handled by a secure gateway (Stripe on the web; App Store or Google Play in the apps). We never see or store your card. Invoices are in My subscription."}]'::jsonb, 'inactive'),
  ('third_parties', 'es', '1.0', '2026-10-01T00:00:00Z', 'Lista pública de terceros', 'Proveedores que tratan datos para prestar el servicio, dónde están y con qué garantías.', '[{"heading":"Supabase","body":"Base de datos, autenticación, archivos y funciones. Unión Europea (eu-west-1)."},{"heading":"Vercel","body":"Alojamiento de la web. Región UE para las funciones; red de entrega global con garantías del Marco de Privacidad de Datos UE-EE. UU. y cláusulas tipo."},{"heading":"Proveedor de SMS","body":"Envío del código OTP. [Por definir, con garantías UE]."},{"heading":"Yoti","body":"Verificación de edad e identidad; solo recibimos el resultado. Reino Unido (decisión de adecuación)."},{"heading":"Mapbox y Google Places","body":"Mapa y datos de locales (las consultas a Google se hacen desde el servidor). EE. UU. (DPF / cláusulas tipo)."},{"heading":"Spotify","body":"Solo si conectas tu Anthem. Unión Europea."},{"heading":"Email transaccional","body":"Documentos firmados y avisos. [Por definir, preferiblemente UE]."},{"heading":"Stripe","body":"Pagos web. Irlanda / EE. UU. Integrado en modo de pruebas y desactivado para el público."},{"heading":"Apple y Google","body":"Compras dentro de las apps y notificaciones push, cuando existan las apps nativas. EE. UU. (DPF)."}]'::jsonb, 'published'),
  ('third_parties', 'en', '1.0', '2026-10-01T00:00:00Z', 'Public list of third parties', 'Providers that process data to run the service, where they are and with what safeguards.', '[{"heading":"Supabase","body":"Database, authentication, files and functions. European Union (eu-west-1)."},{"heading":"Vercel","body":"Web hosting. EU region for functions; global delivery network under the EU-US Data Privacy Framework and standard clauses."},{"heading":"SMS provider","body":"Sends the OTP code. [TBD, with EU safeguards]."},{"heading":"Yoti","body":"Age and identity verification; we only receive the result. United Kingdom (adequacy decision)."},{"heading":"Mapbox and Google Places","body":"Map and venue data (Google is queried from the server). USA (DPF / standard clauses)."},{"heading":"Spotify","body":"Only if you connect your Anthem. European Union."},{"heading":"Transactional email","body":"Signed documents and notices. [TBD, preferably EU]."},{"heading":"Stripe","body":"Web payments. Ireland / USA. Integrated in test mode and disabled for the public."},{"heading":"Apple and Google","body":"In-app purchases and push notifications, once native apps exist. USA (DPF)."}]'::jsonb, 'published');
